@pytest.mark.parametrize("form", CASES)
def test_form_evaluates_to_t(form: str) -> None:
    assert failover.cl_eval_text(form)[-1] is failover.CL_T, form


def test_cases_are_unique() -> None:
    assert len(CASES) == len(set(CASES))
